from pathlib import Path
svg='<svg xmlns="http://www.w3.org/2000/svg" width="680" height="110" viewBox="0 0 680 110" role="img">\n<title>Sponsors/Funding</title><desc>heart sponsors</desc>\n<rect width="680" height="110" rx="16" fill="#0d1117"/>\n<text x="20" y="28" fill="#e6edf3" font-family="monospace" font-size="12">FUNDING — GitHub Sponsors · Buy me a coffee</text>\n<g transform="translate(20,40)">\n  <rect width="160" height="30" rx="8" fill="#ea4aaa"/><text x="80" y="19" text-anchor="middle" fill="white" font-family="monospace" font-size="11">♥ Sponsors</text>\n  <g transform="translate(170,0)"><rect width="160" height="30" rx="8" fill="#FFDD00"/><text x="80" y="19" text-anchor="middle" fill="#000" font-family="monospace" font-size="11">☕ BMC</text></g>\n  <text x="0" y="50" fill="#7d8590" font-family="monospace" font-size="8">.github/FUNDING.yml → sponsors button appears on repo</text>\n</g>\n</svg>\n'
Path(__file__).resolve().parents[2].joinpath('assets','sponsors-card.svg').write_text(svg, encoding='utf-8')
